import sys

MOD = 998244353

def extended_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        g, y, x = extended_gcd(b % a, a)
        return (g, x - (b // a) * y, y)

def mod(a, m):
    return ((a % m) + m) % m

def inverse(a, mod):
    g, x, y = extended_gcd(a, mod)
    if g != 1:
        return 0
    else:
        return (x + 2 * mod) % mod

def mod_fraction(a, b, mod):
    inv_b = inverse(b, mod)
    if inv_b == 0:
        return -1
    else:
        return (inv_b * a) % mod

def solve(N, M, K):
    mod = mod_fraction(1, M, MOD)
    expect = [0] * (K + 1)
    expect[0] = 1
    poly = [0] * (K + 1)
    poly[0] = 1
    curExpect = 1
    for k in range(1, K + 1):
        temp = 1
        for i in range(k):
            temp *= (N - i)
            temp %= MOD
        curExpect = temp * mod % MOD
        for i in range(k, -1, -1):
            poly_i_prev = poly[i - 1] if i > 0 else 0
            poly[i] = (poly_i_prev - (k - 1) * poly[i]) % MOD
        expect[k] = curExpect
        for i in range(k - 1, -1, -1):
            expect[k] -= poly[i] * expect[i]
            expect[k] %= MOD
    print(expect[K])

def main():
    input_line = sys.stdin.readline().strip()
    N_str, M_str, K_str = input_line.split()
    N, M, K = int(N_str), int(M_str), int(K_str)
    solve(N, M, K)

if __name__ == "__main__":
    main()

